  "landing.faq_desc": "If something is missing here, our team responds within one working day.",
  "landing.faq1_q": "Do I need internet on the farm?",
  "landing.faq1_a": "No. The gateway and edge controller keep irrigation rules running offline and sync data whenever a 2G or Wi-Fi connection is available.",
  "landing.faq2_q": "How much does the sensor kit cost?",
  "landing.faq2_a": "A starter kit covering two zones, a tank sensor and a pump controller is priced for a two to four acre holding, with monthly subscription and FPO bulk pricing available.",
  "landing.faq3_q": "How accurate are harvest forecasts?",
  "landing.faq3_a": "Forecasts combine soil history, weather and crop stage models. Accuracy improves through the season and every prediction ships with a confidence band.",
  "landing.faq4_q": "Can buyers contact farmers directly?",
  "landing.faq4_a": "Buyers see forecasts and send procurement requests through FarmGuard. Farmers accept or decline, so no contact details are exposed without consent.",
  "landing.faq5_q": "Which languages are supported?",
  "landing.faq5_a": "English, Hindi, Tamil, Kannada, Malayalam and Telugu across the app, alerts and voice notifications.",
  "landing.faq6_q": "Is my farm data private?",
  "landing.faq6_a": "Farmers own their data. Only aggregated forecast and quality metrics are shared with buyers, and sharing can be turned off at any time.",
