  "landing.wf2_title": "LoRa கேட்வே",
  "landing.wf2_desc": "தகவல்களை திரட்டி 48 மணி நேரம் ஆஃப்லைனில் செயல்படும்",
  "landing.wf3_title": "எட்ஜ் கன்ட்ரோலர்",
  "landing.wf3_desc": "இணையம் இல்லாவிட்டாலும் பாசனத்தை கட்டுப்படுத்தும்",
  "landing.wf4_title": "பார்ம்கார்டு கிளவுட்",
  "landing.wf4_desc": "முன்னறிவிப்பு மாதிரிகள் மற்றும் வணிக நுண்ணறிவு",
  "landing.testimonials_eyebrow": "கள முடிவுகள்",
  "landing.testimonials_title": "விவசாயிகள் மற்றும் வாங்குபவர்கள் நம்புவது",
  "landing.testimonials_desc": "தென்னிந்திய பண்ணைகள் மற்றும் உற்பத்தியாளர் குழுக்களில் பயன்பாட்டில் உள்ளது.",
  "landing.t1_quote": "நான் பாசன நேரத்தை யூகிப்பதை நிறுத்திவிட்டேன். பம்ப் தானாக இயங்குகிறது, டீசல் செலவும் குறைந்தது.",
  "landing.t1_name": "ஆர். செல்வராஜ்",
  "landing.t1_role": "நெல் விவசாயி, தஞ்சாவூர்",
  "landing.t2_quote": "நாங்கள் தக்காளி கொள்முதலை 6 வாரங்களுக்கு முன்பே திட்டமிடுகிறோம். தரக் குறியீடு மிக துல்லியமானது.",
  "landing.t2_name": "பிரியா நாயர்",
  "landing.t2_role": "கொள்முதல் தலைவர், சன்ரைஸ் புட்ஸ்",
  "landing.t3_quote": "எங்கள் சங்கத்தின் 60 பண்ணைகள் பார்ம்கார்டை பயன்படுத்துகின்றன. வாங்குபவர்கள் எங்கள் அளவை நம்புகிறார்கள்.",
  "landing.t3_name": "கே. பிரகாஷ்",
  "landing.t3_role": "FPO செயலாளர், மைசூர்",
  "landing.faq_eyebrow": "அடிக்கடி கேட்கப்படும் கேள்விகள்",
  "landing.faq_title": "விவசாயிகள் மற்றும் வாங்குபவர்கள் கேட்கும் கேள்விகள்",
  "landing.faq_desc": "எங்கள் குழுவினர் விரைவில் பதிலளிப்பார்கள்.",
  "landing.faq1_q": "பண்ணையில் இணையம் தேவையா?",
  "landing.faq1_a": "இல்லை. சென்சார்கள் ஆஃப்லைனில் செயல்பட்டு இணையம் கிடைக்கும்போது தகவலை அனுப்பும்.",
  "landing.faq2_q": "சென்சார் கிட் விலை என்ன?",
  "landing.faq2_a": "சிறு மற்றும் குறு பண்ணைகளுக்கு ஏற்ற குறைந்த கட்டண திட்டங்கள் உள்ளன.",
  "landing.faq3_q": "அறுவடை முன்னறிவிப்பு எவ்வளவு துல்லியமானது?",
  "landing.faq3_a": "மண் வரலாறு மற்றும் வானிலை அடிப்படையில் உயர் துல்லியத்துடன் கணிக்கப்படுகிறது.",
  "landing.faq4_q": "வாங்குபவர்கள் நேரடியாக தொடர்பு கொள்ளலாமா?",
  "landing.faq4_a": "வாங்குபவர்கள் பார்ம்கார்டு வழியாக கொள்முதல் கோரிக்கைகளை அனுப்புவர்.",
  "landing.faq5_q": "எந்தெந்த மொழிகள் உள்ளன?",
  "landing.faq5_a": "ஆங்கிலம், இந்தி, தமிழ், கன்னடம், மலையாளம் மற்றும் தெலுங்கு.",
  "landing.faq6_q": "பண்ணை தரவு பாதுகாப்பானதா?",
  "landing.faq6_a": "விவசாயிகளுக்கே முழு உரிமை. திரட்டப்பட்ட மதிப்பீடுகள் மட்டுமே பகிரப்படும்.",
  "landing.cta_title": "உங்கள் பண்ணையை ஆன்லைனில் கொண்டு வாருங்கள்",
  "landing.cta_desc": "இரண்டு நிமிடங்களில் கணக்கை தொடங்கி பயன்பெறுங்கள்.",
  "landing.cta_create": "கணக்கு தொடங்கு",
  "landing.cta_talk": "எங்களுடன் பேசுங்கள்",
  "landing.footer_desc": "பார்ம்கார்டு பாசனத்தை தானியங்கி ஆக்கி உண்மையான களத் தகவல்களை வழங்குகிறது.",
